def skip_format_url(format_, url):
    """
    Checks whether a give format/url should be skipped and not downloaded.

    @param format_: Filename format (extension).
    @type format_: str (e.g. html, txt, zip, pdf)

    @param url: URL.
    @type url: str

    @return: True if format/url should be skipped, False otherwise.
    @rtype bool
    """
    # Check if format is in the list of skipped formats.
    if format_ in SKIPPED_FORMATS:
        return True

    # Check if url is in the list of skipped urls.
    if url in SKIPPED_URLS:
        return True

    # Check if format is in the list of skipped formats based on the url.
    if format_ in SKIPPED_FORMATS_BASED_ON_URL:
        for skipped_format_based_on_url in SKIPPED_FORMATS_BASED_ON_URL[format_]:
            if skipped_format_based_on_url in url:
                return True

    return False

